  -- the list's battle kind: the first of the mod's set (VRFW_MatchDifficulty) with drops, else 1 / 2 / 4
  local function pick_diff(game)
    local order = {}
    if VRFW_MatchDifficulty ~= nil then
      local okset, set = pcall(VRFW_MatchDifficulty.Set, EVT_CHR_INFO_EVTYPE == 5 and "gate" or "route")
      if okset and type(set) == "table" then
        for d, on in pairs(set) do
          if on then
            order[#order + 1] = d
          end
        end
        table.sort(order)
      end
    end
    for _, d in ipairs({1, 2, 4}) do
      order[#order + 1] = d
    end
    for _, d in ipairs(order) do
      local ok, total = pcall(funcLuaCommand, D.LIST_OF, game, d, 0, 0)
      if ok and type(total) == "number" and total > 0 then
        return d, total
      end
    end
    return 0, 0
  end

  local function hide_rows()
    for k = 0, D.ROWS - 1 do
      cmd(711242136 --[[CMND_SET_LAYER_VISIBLE]], D.LAYER, k, false)
    end
  end

  -- the rows' place: the reward block's own (a mod may move it up with the panel)
  local function place()
    local top = D.TOP
    local ok, _, y = pcall(funcLuaMenuCommand, 2491463760 --[[node translation get]], D.WIN, 0, D.PRESENT)
    if ok and type(y) == "number" then
      top = D.TOP - (y - 490)
