  function D.Draw()
    if D.game == 0 or D.diff == 0 then
      hide_rows()
      return
    end
    local got = {pcall(funcLuaCommand, D.LIST_OF, D.game, D.diff, D.first, D.ROWS)}
    local total = (got[1] and type(got[2]) == "number") and got[2] or 0
    D.total = total
    for k = 0, D.ROWS - 1 do
      local item, pct = got[3 + k * 2], got[4 + k * 2]
      if type(item) == "number" and item ~= 0 then
        pcall(draw_row, k, item, type(pct) == "number" and pct or 0)
      else
        cmd(711242136, D.LAYER, k, false)
      end
    end
  end

  -- the window shows game `game`: its list from the top, the 4 prize icons hidden
  function D.Show(game)
    D.game = (type(game) == "number") and game or 0
    D.first = 0
    D.diff, D.total = pick_diff(D.game)
    if D.diff == 0 then
      hide_rows()
      return false
    end
    for k = 0, 3 do
      cmd(711242136, D.REWARD, k, false)
    end
    place()
    D.Draw()
    return true
  end

  function D.Scroll(dir)
    local last = math.max(0, D.total - D.ROWS)
    local f = math.max(0, math.min(last, D.first + dir))
    if f ~= D.first then
      D.first = f
      D.Draw()
    end
  end

  -- every frame while the window is open: the portraits shown once loaded, the right stick / wheel scroll
  function D.Step()
    if not D.open or D.game == 0 then
      return
    end
    for k = 0, D.ROWS - 1 do
      local t = D.art_t[k]
      if t ~= nil then
        if t <= 0 then
          cmd(D.ALPHA, D.LAYER, k, 1, 1, D.N.art[1])
          D.art_t[k] = nil
        else
          D.art_t[k] = t - 1
        end
      end
    end
    local function on(c)
      local ok, r = pcall(funcLuaCommand, D.CHECK, D.CTRL, c)
      return ok and r == true
    end
    if on(D.W_UP) then
      D.Scroll(-1)
    elseif on(D.W_DOWN) then
      D.Scroll(1)
    end
    local ok, y = pcall(funcLuaCommand, D.ANALOG, 3)
    y = (ok and type(y) == "number") and y or 0
    if math.abs(y) > 0.5 then
      if D.repeat_t <= 0 then
        D.Scroll(y > 0 and -1 or 1)
        D.repeat_t = 8
      else
        D.repeat_t = D.repeat_t - 1
      end
    else
      D.repeat_t = 0
    end
  end
end

local vrfw_crd_setup = SetupInfoWindow
function SetupInfoWindow(a1, ...)
  local r = {vrfw_crd_setup(a1, ...)}
  pcall(VRFW_CrDrops.Show, a1)
  return table.unpack(r)
end

local vrfw_crd_open = OpenCloseInfoWindow
function OpenCloseInfoWindow(a1, a2, ...)
  local r = {vrfw_crd_open(a1, a2, ...)}
  VRFW_CrDrops.open = a2 and true or false
  if not a2 then
    VRFW_CrDrops.art_of = {}
    for k = 0, VRFW_CrDrops.ROWS - 1 do
      pcall(funcLuaMenuCommand, 711242136, VRFW_CrDrops.LAYER, k, false)
    end
  end
  return table.unpack(r)
end

local vrfw_crd_step = Step
function Step(...)
  pcall(VRFW_CrDrops.Step)
  if vrfw_crd_step ~= nil then
    return vrfw_crd_step(...)
  end
end
